export type Brand<TValue, TBrand extends string> = TValue & {
  readonly __brand: TBrand;
};

export type AccountId = Brand<string, "AccountId">;
export type OrgId = Brand<string, "OrgId">;
export type Identifier = string;

export const asAccountId = (value: string): AccountId => value as AccountId;
export const asOrgId = (value: string): OrgId => value as OrgId;

export interface AccountView {
  id: AccountId;
  identifier: Identifier;
  display_name: string;
  org: OrgId | null;
}

export interface ActiveAccountView {
  id: AccountId;
  display_name: string;
  org: OrgId | null;
}

export interface SignedInAccountView {
  account: ActiveAccountView;
  is_active: boolean;
}

export type ListActiveAccountsRequest = Record<never, never>;

export interface ListActiveAccountsResponse {
  accounts: SignedInAccountView[];
}

export interface SwitchActiveAccountRequest {
  target_account_id: AccountId;
}

export interface SwitchActiveAccountResponse {
  active_account_id: AccountId;
  accounts: SignedInAccountView[];
}

export type AccountFailureCode =
  | "duplicate_identifier"
  | "invalid_credential"
  | "validation_failed"
  | "invitation_not_found"
  | "invitation_expired"
  | "invitation_already_consumed"
  | "target_account_not_signed_in";
